with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'chillreflexologybali.com' and status = 'active' and publication_status = 'published' order by slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Chill Reflexology treatment prices', 1, 'draft', 'partial', 'https://chillreflexologybali.com/', 'Official Chill Reflexology price list',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'db00312a55a27b02b28e3ad53633a73340564bba7c6e630461d231c61d0ef8f8', 'spa'
  from target t
