with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'bodyworshipbali.com' and status = 'active' and publication_status = 'published' order by slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Body Worship Bali treatment prices', 1, 'draft', 'partial', 'https://bodyworshipbali.com/our-services/', 'Official Body Worship Bali price list',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '18ef4ae951ab80fbf7937deb59c678d4b6dab60d13a91a58f3f1c5b6311d5ea2', 'spa'
