join (values ('Manicure', 'Express Manicure (45 min)', 'This manicure will keep your hands and nails looking fabulous. Enjoy cuticle therapy and nail file before the finishing touch, a fresh polish application in your favourite colour.', 200000, 'IDR', 0), ('Manicure', 'Gel Polish Manicure (60 min)', 'An express manicure including the application of quick-drying, chip-free, long lasting Shellac or The Perfect Match gel polish - providing a high gloss shine.', 365000, 'IDR', 1), ('Manicure', 'Dipping Powder Manicure (75 min)', 'Also known as SNS, this nail treatment uses a coloured powder to create a long-lasting and durable finish. This type of manicure is similar to Gel and quite resistant to chipping and fading.', 475000, 'IDR', 2), ('Manicure', 'BIAB – Builder (Gel) in a Bottle Manicure (75 min)', 'Experience this revolutionary nail treatment, designed for naturally stronger, longer nails. Our must-have builder gel creates a gentle yet resilient overlay, promoting nail health and encouraging natural growth for a flawless and longer lasting finish.', 520000, 'IDR', 3), ('Manicure', 'Kiddie Manicure (30 min)', null, 90000, 'IDR', 4), ('Pedicure', 'Express Pedicure (45 min)', 'This pedicure includes a brief callous being removal, nail filing and shaping and finishing with a polish application in your favourite colour.', 235000, 'IDR', 0), ('Pedicure', 'Gel Polish Pedicure (60 min)', 'An express pedicure including the application of quick-drying, chip-free, long lasting Shellac or The Perfect Match gel polish - providing a high gloss shine.', 365000, 'IDR', 1), ('Pedicure', 'Kiddie Pedicure (30 min)', null, 90000, 'IDR', 2), ('Other', 'Add-on Extra Callous Treatment (15 min)', null, 80000, 'IDR', 0), ('Other', 'Pretty Hands (70 min)', 'Indulge yourself in this lavish, premium hand treatment which includes cuticle therapy, a relaxing hand massage for circulation and parafin dip that leaves your hands irresistibly soft and smooth. The final touch is an expert polish application with the colour of your choice.', 330000, 'IDR', 1), ('Other', 'Happy Feet (70 min)', 'Our premium, results oriented pedicure treatment includes a smoothing exfoliation, thorough callous removal and a stimulating foot massage. This is followed by a cooling mint foot mask to soften, moisturise and freshen, then finished with an expert polish application with the colour of your choice.', 355000, 'IDR', 2), ('Other', 'Hard Gel / Acrylic Extensions - Full Set (120 min)', null, 650000, 'IDR', 3), ('Other', 'Hard Gel / Acrylic Extensions - Overlay', null, 630000, 'IDR', 4), ('Other', 'Hard Gel / Acrylic Extensions - Re-fill', null, 525000, 'IDR', 5), ('Other', 'Back Therapy (60 min)', 'Thirty minutes of melting moments focused on your back to release knots and tension.', 155000, 'IDR', 6), ('Other', 'Rejuvenate Anti-Ageing Oxygen (60 min)', 'This skin quenching treatment provides the ultimate in intense hydration. Perfect for all skin types, the Rejuvenate Professional Serum contains vitamins and antioxidants that dramatically lift, tone and hydrate the skin.', 1250000, 'IDR', 7), ('Other', 'Opulence Brightening Oxygen (60 min)', 'Reveal a more radiant you with botanical brighteners and super concentrated Vitamin C to brighten and balance dull, uneven skin tone. Pigmentation is minimised, leaving skin luminous and toned.', 1250000, 'IDR', 8), ('Other', 'Clarity Healing Oxygen (60 min)', 'Refines the appearance of problem prone skin with the ultimate weapon against impurities and irritation.', 1550000, 'IDR', 9), ('Other', 'Rejuvenate Anti-Ageing Oxygen with Antioxidants (75 min)', null, 1575000, 'IDR', 10), ('Other', 'Add-on for Atoxolene Anti-Wrinkle (15 min)', null, 615000, 'IDR', 11), ('Other', 'Athena Microdermabrasion (45 min)', 'Our microdermabrasion facial by Athena is a non-surgical, non-chemical and non-invasive method of skin resurfacing. By removing the outer layers of the skin, collagen production is stimulated along with cellular renewal to improve skin tone and reduce wrinkles.', 590000, 'IDR', 12), ('Other', 'Age Smart by Dermalogica (75 min)', 'Revitalise your skin with this powerful solution to help smooth away the signs of ageing. Packed with an advanced formula of Vitamin C, anti-oxidants and Lactic Acid.', 890000, 'IDR', 13), ('Other', 'Active Cleansing by Dermalogica (75 min)', 'Achieve calmer, clearer skin with this cleansing facial that helps to reduce excess oil, congestion and inflammation.', 775000, 'IDR', 14), ('Other', 'Ultra Calming by Dermalogica (75 min)', 'Experience longer lasting relief from sensitive skin flare-ups, itching, burning or redness - common signs of sensitive skin.', 760000, 'IDR', 15), ('Other', 'Island Indulgence (150 min)', 'Immerse yourself in the spirit of the island with this three-part indulgence. Begin with a relaxing 60 mins Balinese Massage, followed by a 30 mins Coconut Body Scrub to gently exfoliate and nourish the skin.', 650000, 'IDR', 16), ('Other', 'Beauty Express (120 min)', 'Enjoy 60 minutes of Refreshing Facial along with our Express Manicure and Express Pedicure. In just two hours - present a new you to the world.', 650000, 'IDR', 17), ('Other', 'Delight Me (75 min)', 'Two Therapists will treat you with this combination of Argan Oil Hair Cream Mask and Foot Reflexology together. A full 60 minutes hair treatment will get the sun, sea and sand out of your hair, bringing back its natural condition and shine.', 440000, 'IDR', 18), ('Other', 'Lost in Paradise', 'A truly unique Spa experience of indulgent proportions. Be pampered from head to toe with our all encompassing treatment package that includes 60 minutes of Balinese Massage, a 60 minute Refreshing Facial, Express Manicure and Express Pedicure and finishing with a luxurious Hair Cream Bath.', 1235000, 'IDR', 19), ('Other', 'RF Anti-Cellulite Treatment - Upper Thigh (120 min)', 'This non-invasive treatment harnesses radio-frequency (RF) technology to break down fat cells, restructure collagen fibers, and stimulate collagen production - helping to smooth, firm and tighten the skin while reducing the appearance of cellulite.', 900000, 'IDR', 20), ('Other', 'RF Anti-Cellulite Treatment - Stomach (60 min)', null, 650000, 'IDR', 21), ('Other', 'Add-on Upper Arm (45 min)', null, 400000, 'IDR', 22), ('Other', 'Upper Lip Hair Removal (5 min)', null, 135000, 'IDR', 23), ('Other', 'Cheeks Hair Removal (5 min)', null, 220000, 'IDR', 24), ('Other', 'Nose Hair Removal (5 min)', null, 80000, 'IDR', 25), ('Other', 'Chin Hair Removal (5 min)', null, 130000, 'IDR', 26), ('Other', 'Underarm Hair Removal (15 min)', null, 195000, 'IDR', 27), ('Other', 'Bikini Line Hair Removal (20 min)', null, 220000, 'IDR', 28), ('Other', 'G-String Hair Removal (30 min)', null, 285000, 'IDR', 29), ('Other', 'Brazillian Hair Removal (45 min)', null, 350000, 'IDR', 30), ('Other', 'Half Arm Hair Removal (20 min)', null, 225000, 'IDR', 31), ('Other', 'Full Arm Hair Removal (20 min)', null, 275000, 'IDR', 32), ('Other', 'Half Leg Hair Removal (20 min)', null, 285000, 'IDR', 33), ('Other', 'Three Quarter Leg Hair Removal (30 min)', null, 345000, 'IDR', 34), ('Other', 'Full Leg Hair Removal (60 min)', null, 375000, 'IDR', 35), ('Other', 'Back Hair Removal (25 min)', null, 360000, 'IDR', 36), ('Other', 'Chest Hair Removal (25 min)', null, 255000, 'IDR', 37), ('Other', 'Stomach Hair Removal (15 min)', null, 265000, 'IDR', 38), ('Other', 'Chest & Stomach Hair Removal (30 min)', null, 420000, 'IDR', 39), ('Nails', 'Nail Extension Removal (30 min)', null, 170000, 'IDR', 0), ('Nail Art', 'Add-on Nail Art (full set)', null, 75000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage with Sand Compress (90 min)', 'Incorporating an oil blend massage and heated sand compress, this unique treatment combines traditional Balinese massage techniques to relieve muscle tension, stiffness, pain and fatigue. Designed to stimulate the blood circulation while increasing energy levels, the warm sand promotes flexibility and deep relaxation.', 280000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'This powerful healing and energizing massage uses pressure point, kneading and friction techniques to release deep muscle tension, stimulating the body’s systems and re-balance the natural life-force.', 290000, 'IDR', 0), ('Traditional Massage', 'The Nest Signature Massage (90 min)', 'A fusion of Balinese and Thai massage techniques in purposeful designed movements. Experience pressure point, stretching techniques and followed with a deep yet relaxing massage movement to stimulate the circulation and relax the muscles.', 410000, 'IDR', 0), ('Traditional Massage', 'Serenity Candle Massage (90 min)', 'A full body massage with medium pressure designed to nourish and rehydrate the skin. A special candle is burned to release a body butter and its essential oil, which is then gently poured and massaged onto the body.', 395000, 'IDR', 1), ('Traditional Massage', 'Therapeutic Massage (105 min)', 'Is there any specific area on your body where you feel the most pain? Maybe just your back or your legs? This massage is designed to focus on the specific problem area you are experiencing. The time spent on this specific problem area can take up most of your massage session.', 360000, 'IDR', 2), ('Hot Stone', 'Warm Stone Massage (90 min)', 'A luxurious healing stone massage therapy melts away tension, eases muscle stiffness, increasing blood circulation and your metabolism.', 400000, 'IDR', 0), ('Lymphatic Massage', 'Lymphatic Drainage Massage (75 min)', 'Our Lymphatic Drainage Massage uses the Vodder technique, a specialised approach that stimulates the lymphatic system, reduces inflammation and water retention, and enhances the immune system.', 410000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (30 min)', 'This foot therapy focuses on the feet to positively affect the whole body. Reflexology works on precise points on the feet that are believed to ‘reflex’ to other parts of the body.', 130000, 'IDR', 0), ('Reflexology', 'Foot Reflexology With Peppermint Foot Mask (60 min)', 'Added to the above, a tingly but soothing Peppermint Foot mask that will leave you fresh footed and ready to take on the world.', 235000, 'IDR', 1), ('Body Scrub', 'Coconut Body Scrub (45 min)', null, 190000, 'IDR', 0), ('Body Scrub', 'Sea Salt Scrub (45 min)', null, 190000, 'IDR', 1), ('Body Scrub', 'Pre-Sun Body Scrub & Hydrator (90 min)', 'Prepare your skin for the sun and optimise your tanning with this light Body Wash and Rice Milk exfoliation.', 420000, 'IDR', 2), ('Facial', 'Oxygen Facials by Intraceuticals (60 min)', 'This ''celebrity'' Oxygen Facial is a truly unique experience. Treatments provide instant results with fine lines and blemishes appearing visibly reduced. Your skin looks rejuvenated, radiant and fresh - what more could you ask for?', 1250000, 'IDR', 0), ('Hydrating Facial', 'Hydrating by Dermalogica (75 min)', 'Experience the transformative benefits of this unique rice-based enzyme powder, combined with a botanical brightening complex that gently micro-foliates to remove dead skin cells whilst hydrating to help smooth wrinkles and fine lines.', 760000, 'IDR', 0), ('Balinese Boreh', 'Balinese Boreh Body Wrap (90 min)', 'Experience an authentic, century old Balinese Boreh energising treatment that is still used today as a health remedy. A traditional warm spice wrap helps to relieve tension, aches and increase blood circulation. While cocooned in the wrap, enjoy a scalp massage followed by a relaxing massage.', 440000, 'IDR', 0), ('Body Wrap', 'Seaweed Body Wrap (135 min)', 'This oxygenated body exfoliation enhances the penetration of seaweed minerals and follows with a Seaweed Body Mask to help detoxify, re-mineralize and eliminate water retention.', 650000, 'IDR', 0), ('Body Wrap', 'After Sun Cooling Body Wrap (60 min)', 'This soothing body treatment is ideal for sun exposed skin. A light refreshing Lavender Oil gel is applied to promote the healing of the skin and give it a more youthful and healthy appearance.', 335000, 'IDR', 1), ('Brows', 'Eyebrow Hair Removal (15 min)', null, 160000, 'IDR', 0), ('Brows', 'Refectocil Brow Tinting', null, 175000, 'IDR', 1), ('Neck & Shoulder', 'Shoulders Hair Removal (20 min)', null, 210000, 'IDR', 0), ('Lashes', 'Eyelash Extensions - Russian Volume Full Set (120 min)', 'Add 20 to 25 more lashes per eye. Made from 100% natural Silk fibres, grafted onto your own lashes and lasting approximately 2 - 3 weeks!', 625000, 'IDR', 0), ('Lashes', 'Eyelash Extensions - Russian Volume Re-Fill Set (60 min)', null, 495000, 'IDR', 1), ('Lashes', 'Eyelash Extensions - Natural Full Set (120 min)', null, 595000, 'IDR', 2), ('Lashes', 'Eyelash Extensions - Natural Re-Fill Set (60 min)', null, 460000, 'IDR', 3), ('Lashes', 'Eyelash Extension Removal (30 min)', null, 200000, 'IDR', 4), ('Lashes', 'Refectocil Eyelash Tinting', null, 175000, 'IDR', 5), ('Head Massage', 'Eyelash Lift + Head Massage (45 min)', null, 340000, 'IDR', 0), ('Cream Bath', 'Hair Cream Bath by Loreal (60 min)', 'Enjoy one of these traditional and lavish Indonesian hair treatments, that includes the application of a rich conditioning cream massaged into the hair and scalp before enjoying a head, neck and shoulder massage. This is followed with a hair wash and optional / brief hair drying.', 250000, 'IDR', 0), ('Hair Treatment', 'Argan Oil Hair Mask (60 min)', null, 280000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'saridayspa.com' and status = 'active' and publication_status = 'published' order by slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Sari Day Spa treatment prices', 1, 'draft', 'partial', 'https://saridayspa.com/spa-menu', 'Official Sari Day Spa price list',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, '7f5868202cc59ca9d6b97d786c696a73394421c2f6f505175c30ccd52e5a23f5', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Traditional Massage', 0), ('Deep Tissue', 1), ('Balinese Massage', 2), ('Hot Stone', 3), ('Foot Massage', 4), ('Reflexology', 5), ('Body Scrub', 6), ('Body Mask', 7), ('Manicure', 8), ('Pedicure', 9), ('Other', 10), ('Nails', 11), ('Scalp Treatment', 12), ('Spa Package', 13), ('Nail Art', 14)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Sari Signature Relaxing Massage (60 min)', 'A gentle, rhythmic massage designed to promote relaxation and improve circulation.', 195000, 'IDR', 0), ('Traditional Massage', 'Sari Signature Relaxing Massage (90 min)', 'A gentle, rhythmic massage designed to promote relaxation and improve circulation.', 295000, 'IDR', 1), ('Traditional Massage', 'Magical Mini Massage (45 min)', 'A gentle full-body massage designed just for kids, using kid-friendly oils.', 100000, 'IDR', 2), ('Deep Tissue', 'Deep Tissue Massage (60 min)', 'Targets deep muscle layers to relieve chronic pain and stiffness.', 195000, 'IDR', 0), ('Deep Tissue', 'Deep Tissue Massage (90 min)', 'Targets deep muscle layers to relieve chronic pain and stiffness.', 295000, 'IDR', 1), ('Balinese Massage', 'Balinese Massage (60 min)', 'A combination of deep pressure, acupressure, and stretching to relieve tension and improve circulation.', 195000, 'IDR', 0), ('Balinese Massage', 'Balinese Massage (90 min)', 'A combination of deep pressure, acupressure, and stretching to relieve tension and improve circulation.', 295000, 'IDR', 1), ('Hot Stone', 'Hot Stone Massage (90 min)', 'Uses heated stones to ease muscle tension and enhance relaxation.', 350000, 'IDR', 0), ('Foot Massage', 'Foot Massage (60 min)', 'Designed to relieve tension and improve circulation.', 165000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (60 min)', 'A therapeutic treatment that stimulates pressure points to promote overall wellness.', 185000, 'IDR', 0), ('Reflexology', 'Foot Reflexology (90 min)', 'A therapeutic treatment that stimulates pressure points to promote overall wellness.', 225000, 'IDR', 1), ('Body Scrub', 'Body Scrub (60 min)', 'A rejuvenating treatment that exfoliates and renews your skin, enhancing circulation.', 200000, 'IDR', 0), ('Body Mask', 'Body Mask (60 min)', 'Designed to detoxify, hydrate, and nourish your skin, leaving you feeling refreshed.', 285000, 'IDR', 0), ('Manicure', 'Classic Manicure (60 min)', 'A classic manicure with OPI or gel polish delivers timeless elegance.', 185000, 'IDR', 0), ('Manicure', 'Classic Manicure (75 min)', 'With Gel Polish', 285000, 'IDR', 1), ('Pedicure', 'Spa Pedicure (75 min)', 'A classic pedicure with OPI or gel polish offers luxurious care and flawless shine.', 200000, 'IDR', 0), ('Pedicure', 'Spa Pedicure (90 min)', 'With Gel Polish', 300000, 'IDR', 1), ('Other', 'The Classic Mani-pedi (90 min)', 'The perfect blend of relaxation and beauty, leaving your hands and feet beautifully polished.', 350000, 'IDR', 0), ('Other', 'The Classic Mani-pedi (120 min)', 'With Gel Polish', 450000, 'IDR', 1), ('Other', 'Add OPI Polish (20 min)', 'Offers a fun, luxurious finish that’s perfect for any occasion.', 100000, 'IDR', 2), ('Other', 'File and OPI Polish (30 min)', 'Combines expert nail care with a fun, luxurious finish.', 110000, 'IDR', 3), ('Other', 'Tiny Toes & Twinkle Fingers (45 min)', 'A playful manicure and pedicure experience with fun colour and a light hand and foot massage.', 100000, 'IDR', 4), ('Nails', 'Remove Gel Polish (20 min)', 'A gentle gel polish removal that protects your natural nails.', 70000, 'IDR', 0), ('Nails', 'Add Gel Polish (25 min)', 'Delivers a glossy, long-lasting finish.', 150000, 'IDR', 1), ('Nails', 'File and Gel Polish (45 min)', 'Offers a sleek, luxurious finish that’s durable and stunning.', 175000, 'IDR', 2), ('Scalp Treatment', 'Hair & Scalp Revitalizing Treatment (75 min)', 'Featuring nourishing shampoo, conditioner, and hair oil with a soothing massage.', 295000, 'IDR', 0), ('Spa Package', 'Princess Pamper Package (90 min)', 'Includes Magical Mini Massage and Tiny Toes & Twinkle Fingers for a full hour of pampering.', 150000, 'IDR', 0), ('Nail Art', 'Glitter Nail Art (30 min)', 'Perfect for birthdays, playdates, or a special day of self-care.', 75000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

with target as (
  select slug from venues where split_part(regexp_replace(regexp_replace(official_url, '^https?://', ''), '^www\.', ''), '/', 1) = 'koashala.com' and status = 'active' and publication_status = 'published' order by slug limit 1
), m as (
  insert into menus (venue_slug, title, version, status, completeness, source_url, source_label,
                     captured_at, verified_at, expires_at, content_digest, kind)
  select t.slug, 'Koa Spa treatment prices', 1, 'draft', 'partial', 'https://www.koashala.com/spa', 'Official Koa Spa price list',
         '2026-08-25T01:47:06+00:00'::timestamptz, null, '2026-11-23T01:47:06+00:00'::timestamptz, 'cf9bb62ee314677b5d411180fcdc924983f483fd8cc490f5b95c71d6b80782c8', 'spa'
  from target t
  where not exists (select 1 from menus x, target t2 where x.venue_slug = t2.slug and x.kind = 'spa')
  returning id
), secs as (
  insert into menu_sections (menu_id, name, position)
  select m.id, s.name, s.pos from m, (values ('Traditional Massage', 0), ('Other', 1), ('Balinese Massage', 2), ('Reflexology', 3), ('Hot Stone', 4), ('Shirodhara', 5)) as s(name, pos)
  returning id, name
)
insert into menu_items (menu_id, section_id, name, description, price_minor, currency, position)
select m.id, secs.id, i.name, i.descr, i.price, i.cur, i.pos
from m, secs
join (values ('Traditional Massage', 'Massage 90 minute treatment (90 min)', null, 420000, 'IDR', 0), ('Traditional Massage', 'Customise your massage with our add ons (30 min)', null, 200000, 'IDR', 1), ('Other', 'The Herbalist', 'Steamed herbal poultices are pressed into muscles combined with a deeply nurturing massage using traditional Jamu herb infused oil made exclusively for Koa. Enjoy a chamomile tea eye pillow to finish your refreshing therapeutic treatment.', 520000, 'IDR', 0), ('Other', 'Mother Earth', 'Your body is caressed with the flowing strokes of warm basalt stones combined with soothing massage using our unique oil blend of Agarwood, Patchouli and Musk. Fall into a deep state of relaxation with a chai infused eye pillow. Connect with earth energy in this deeply calming and grounding treatment.', 290000, 'IDR', 1), ('Other', 'Chakra Dhara', 'This treatment is based on ancient Indian holistic healing traditions. We start by awakening the skin by dry brushing the body. This improves circulation and removes impurities. Followed by an invigorating Ayurvedic style massage using a deeply nourishing warmed oil blend of Neroli, Rose, white musk with a hint of cinnamon.', 290000, 'IDR', 2), ('Other', 'Aura Harmony', 'This signature massage is a fusion of aura cleansing spray, chakra crystal layout, be lulled into a state of bliss with an aromatherapy body massage, drifting on the scent of lavender & bergamot working on both the physical and auric body you will feel an amazing lightness of being. We finish off your treatment with a singing bowl.', 290000, 'IDR', 3), ('Other', 'Nuad Boran', 'Originating from Buddhist monks this dry style massage combines stretching, gentle twisting and acupressure. No oil is applied and kimono is supplied. Finish off with a dry head and face massage while enjoying a lemongrass infused hot towel foot wrap.', 290000, 'IDR', 4), ('Other', 'Chi Reviver', 'This massage is a powerful energy reviver. Firm massage, kneading and pressure point techniques get deep into the muscles, relieving tension and improving the chi energy meridians. Eucalyptus, rosemary and lavender oils assist in the healing and rebalancing of the life force. Finished with a eucalyptus hot towel neck roll.', 290000, 'IDR', 5), ('Balinese Massage', 'Balinese Hands', 'A beautiful massage combining kneading and rhythmic strokes of balinese hands and our dreamy ylangylang, coconut and vanilla oil blend will have you floating in tropical island bliss. We will treat your feet to a ylang-ylang scrub.', 290000, 'IDR', 0), ('Reflexology', 'Reflexology', 'Begin with a refreshing lavender foot soak, followed by our signature pressure point foot massage from the knees down. This refined reflexology treatment helps restore balance, enhance circulation, and awaken the body’s natural healing energy, perfect for deep relaxation and revitalized legs.', 290000, 'IDR', 0), ('Hot Stone', 'Hot Stone Reflexology', 'Start with a refreshing lavender foot soak, lemon pandan foot scrub and peppermint green tea foot mask. Then enjoy an intensive foot and lower leg massage using acupressure on precise points on the feet to open meridians and enhance the bodies natural healing abilities. To bring balance to the treatment we finish with hot stone shoulder and neck massage.', 290000, 'IDR', 0), ('Shirodhara', 'Shirodhara (75 min)', 'This Ayurvedic healing technique combines indian head massage include face, neck, shoulder massage completed by pouring warm coconut oil on the third eye area. This is the perfect treatment to completely quieten a busy mind having a soothing and balancing effect on brain cells while gently activating our intuition. Treatment 60 mins + 15 mins shower time.', 320000, 'IDR', 0)) as i(sec, name, descr, price, cur, pos) on i.sec = secs.name;

update menus set status = 'source_snapshot', source_snapshot_published_at = '2026-08-25T01:47:06+00:00'::timestamptz
where status = 'draft'
  and completeness = 'partial'
  and verified_at is null
  and content_digest is not null
  and expires_at > now()
  and created_at >= '2026-08-25T01:47:06+00:00'::timestamptz
  and exists (select 1 from menu_sections s join menu_items it
              on it.section_id = s.id and it.menu_id = s.menu_id
              where s.menu_id = menus.id);
